def f(I):
    h,w=len(I),len(I[0]); O=[r[:] for r in I]
    cols=set(); rows=set()
    for r in range(h):
        for c in range(w):
            if I[r][c]==1: cols.add(c); rows.add(r)
    # fill marker rows+cols with 1; recolor any 2-block cell inside a filled row/col to 1
    for c in cols:
        for r in range(h):
            if O[r][c]==2: O[r][c]=1
    for r in rows:
        for c in range(w):
            if O[r][c]==2: O[r][c]=1
    return O
