                        a_,b_=x+dx,y+dy
                        if 0<=a_<H and 0<=b_<W and g[a_][b_]==2 and not seen[a_][b_]:
                            seen[a_][b_]=True; q.append((a_,b_))
                r0,r1,c0,c1=min(p[0] for p in cells),max(p[0] for p in cells),min(p[1] for p in cells),max(p[1] for p in cells)
                if any(r0<=rr<=r1 and c0<=cc<=c1 for rr,cc in painted):
                    for x,y in cells: res[x][y]=1
    return res

